'use strict';

function buildActivationPlan(components) {
  if (!Array.isArray(components)) {
    throw new TypeError('components must be an array');
  }

  const dependencies = new Map();
  for (const component of components) {
    if (!component || typeof component !== 'object' || Array.isArray(component) ||
        typeof component.name !== 'string' || component.name.length === 0 ||
        !Array.isArray(component.dependsOn) ||
        component.dependsOn.some((name) => typeof name !== 'string')) {
      throw new TypeError('invalid component');
    }
    if (dependencies.has(component.name)) {
      throw new RangeError('duplicate component name');
    }
    if (new Set(component.dependsOn).size !== component.dependsOn.length) {
      throw new RangeError('duplicate dependency');
    }
    dependencies.set(component.name, new Set(component.dependsOn));
  }

  for (const required of dependencies.values()) {
    for (const name of required) {
      if (!dependencies.has(name)) {
        throw new RangeError('missing dependency');
      }
    }
  }

  const remaining = new Set(dependencies.keys());
  const completed = new Set();
  const plan = [];

  while (remaining.size > 0) {
    const layer = Array.from(remaining)
      .filter((name) => Array.from(dependencies.get(name)).every((item) => completed.has(item)));
    if (layer.length === 0) {
      throw new Error('dependency cycle');
    }
    plan.push(layer);
    for (const name of layer) {
      remaining.delete(name);
      completed.add(name);
    }
  }

  return plan;
}

module.exports = buildActivationPlan;

