'use strict';

const assert = require('node:assert');
const buildActivationPlan = require('./solution');

assert.strictEqual(typeof buildActivationPlan, 'function');
assert.deepStrictEqual(buildActivationPlan([]), []);

const components = [
  { name: 'web', dependsOn: ['api', 'cache'] },
  { name: 'db', dependsOn: [] },
  { name: 'worker', dependsOn: ['db'] },
  { name: 'cache', dependsOn: [] },
  { name: 'api', dependsOn: ['db'] },
  { name: 'metrics', dependsOn: [] }
];
const snapshot = JSON.stringify(components);
assert.deepStrictEqual(buildActivationPlan(components), [
  ['cache', 'db', 'metrics'],
  ['api', 'worker'],
  ['web']
]);
assert.strictEqual(JSON.stringify(components), snapshot);

const frozen = Object.freeze([
  Object.freeze({ name: 'b', dependsOn: Object.freeze(['a']) }),
  Object.freeze({ name: 'a', dependsOn: Object.freeze([]) })
]);
assert.deepStrictEqual(buildActivationPlan(frozen), [['a'], ['b']]);

for (const invalid of [null, {}, 'components']) {
  assert.throws(() => buildActivationPlan(invalid), TypeError);
}
for (const invalid of [
  [null],
  [{ name: '', dependsOn: [] }],
  [{ name: 4, dependsOn: [] }],
  [{ name: 'a', dependsOn: 'b' }],
  [{ name: 'a', dependsOn: [3] }]
]) {
  assert.throws(() => buildActivationPlan(invalid), TypeError);
}
assert.throws(
  () => buildActivationPlan([{ name: 'a', dependsOn: [] }, { name: 'a', dependsOn: [] }]),
  RangeError
);
assert.throws(() => buildActivationPlan([{ name: 'a', dependsOn: ['missing'] }]), RangeError);
assert.throws(
  () => buildActivationPlan([{ name: 'a', dependsOn: [] }, { name: 'b', dependsOn: ['a', 'a'] }]),
  RangeError
);
assert.throws(
  () => buildActivationPlan([{ name: 'a', dependsOn: ['b'] }, { name: 'b', dependsOn: ['a'] }]),
  Error
);

